bool stratum_init(struct pool *pool) {
    json_t *req, *resp, *result;
    char *sid = NULL;
    int nonce = 0;
    bool success = false;

    if (!stratum_subscribe(pool, &sid, &nonce)) {
        applog(LOG_NOTICE, "Stratum subscribe failed for %s", pool->rpc_url);
        if (sid)
            free(sid);
        return false;
    }

    resp = stratum_send_rpc(pool, "mining.authorize", pool->rpc_user, pool->rpc_pass);
    if (!resp) {
        applog(LOG_NOTICE, "Stratum authorize failed for %s", pool->rpc_url);
        free(sid);
        return false;
    }

    result = json_object_get(resp, "result");
    if (!result || !json_is_array(result)) {
        applog(LOG_NOTICE, "Invalid Stratum authorize response from %s", pool->rpc_url);
        json_decref(resp);
        free(sid);
        return false;
    }

    pool->session_id = sid;
    pool->nonce = nonce;
    success = true;

    json_decref(resp);

    return success;
}

bool stratum_init(struct pool *pool) {
    jsonrpc_request request;
    jsonrpc_response response;
    char *req_str = NULL;
    char *sub_req;
    int retry = 0;

    pool->session_id[0] = '\0';
    pool->nonce[0] = '\0';
    pool->job_id[0] = '\0';

    while (retry < 2) {
        if (retry == 1)
            loginfo("Stratum retrying without session ID");

        sub_req = retry ? "{ \"params\": [\"\", \"\"], \"id\": 1, \"jsonrpc\": \"2.0\", \"method\": \"mining.subscribe\" }"
                        : "{ \"params\": [\"miner0\", \"\"], \"id\": 1, \"jsonrpc\": \"2.0\", \"method\": \"mining.subscribe\" }";

        req_str = jsonrpc_make_request(sub_req, &request);
        if (!req_str) {
            logerr("Failed to create JSON-RPC request");
            return false;
        }

        if (!jsonrpc_send(pool->sock, req_str)) {
            logerr("Failed to send subscription request");
            free(req_str);
            return false;
        }

        free(req_str);
        req_str = jsonrpc_recv(pool->sock, &response);
        if (!req_str) {
            logerr("Failed to receive subscription response");
            return false;
        }

        if (response.error) {
            logerr("Subscription request error: %s", response.error);
            free(req_str);
            return false;
        }

        if (!jsonrpc_get_result(response.result, &request)) {
            logerr("Failed to parse subscription result");
            free(req_str);
            return false;
        }

        if (!request.params || request.params[0] == NULL || request.params[1] == NULL || request.params[2] == NULL) {
            logerr("Incomplete subscription response");
            free(req_str);
            return false;
        }

        strncpy(pool->session_id, request.params[0], sizeof(pool->session_id) - 1);
        strncpy(pool->nonce, request.params[1], sizeof(pool->nonce) - 1);
        strncpy(pool->job_id, request.params[2], sizeof(pool->job_id) - 1);

        pool->session_id[sizeof(pool->session_id) - 1] = '\0';
        pool->nonce[sizeof(pool->nonce) - 1] = '\0';
        pool->job_id[sizeof(pool->job_id) - 1] = '\0';

        loginfo("Stratum session ID: %s", pool->session_id);
        loginfo("Stratum nonce: %s", pool->nonce);
        loginfo("Stratum job ID: %s", pool->job_id);

        free(req_str);
        return true;
    }

    logerr("Stratum subscription failed after retries");
    return false;
}

bool stratum_init(struct pool *pool) {
    json_t *val, *resp;
    char *sid = NULL;
    int retry = 0;
    bool ret = false;

    do {
        val = json_object();
        if (!val)
            goto out;

        json_object_set_new(val, "id", json_integer(1));
        json_object_set_new(val, "method", json_string("mining.subscribe"));
        json_object_set_new(val, "params", json_array());

        if (!stratum_send_recv(pool, val, &resp)) {
            if (retry++ == 0) {
                /* Retry without session ID */
                goto retry;
            } else {
                applog(LOG_NOTICE, "Stratum subscribe failed for pool %d", pool->pool_no);
                goto out;
            }
        }

        if (!json_is_array(resp)) {
            applog(LOG_NOTICE, "Stratum subscribe response invalid");
            goto out;
        }

        if (json_array_size(resp) < 3)
            goto out;

        val = json_array_get(resp, 0);
        if (!val || !json_is_string(val))
            goto out;

        sid = strdup(json_string_value(val));
        if (!sid)
            goto out;

        val = json_array_get(resp, 1);
        if (!val || !json_is_array(val))
            goto out;

        pool->session_id = strdup(json_string_value(json_array_get(val, 0)));
        pool->nonce = strdup(json_string_value(json_array_get(val, 1)));

        if (!pool->session_id || !pool->nonce)
            goto out;

        ret = true;
    } while (0);

out:
    if (resp)
        json_decref(resp);
    return ret;
}

bool stratum_init(struct pool *pool) {
    json_rpc_req *req;
    struct work work;
    char *subscription, *id_str;
    char agent[64];
    bool ret = false;
    int attempts = 0;
    int max_attempts = 2;

    req = json_rpc_req_new("mining.subscribe", NULL, pool->rpc_id++);
    json_rpc_req_add_params(req, "[]");

    if (!req) {
        applog(LOG_ERR, "Failed to create JSON-RPC request for mining.subscribe");
        return false;
    }

    if (opt_protocol) {
        snprintf(agent, sizeof(agent), "CGMiner/%s", CGMINER_VERSION);
        json_rpc_req_set_header(req, "User-Agent", agent);
    }

    ret = json_rpc_call(pool, req, &work.resp, 0);
    json_rpc_req_free(req);

    if (!ret) {
        applog(LOG_ERR, "Stratum subscription request failed for pool %d", pool->num);
        return false;
    }

    if (!work.resp) {
        applog(LOG_ERR, "No response from Stratum server for pool %d", pool->num);
        return false;
    }

    subscription = json_get_string(work.resp, "result", 0);
    if (!subscription) {
        applog(LOG_ERR, "No subscription result from Stratum server for pool %d", pool->num);
        return false;
    }

    id_str = strdup(subscription);
    if (!id_str) {
        applog(LOG_ERR, "Failed to allocate memory for session ID");
        return false;
    }

    pool->session_id = id_str;
    pool->stratum_active = true;
    applog(LOG_NOTICE, "Stratum session initiated for pool %d with session ID: %s", pool->num, pool->session_id);

    return true;
}

bool stratum_init(struct pool *pool) {
    json_rpc *req;
    json_tokener *tok;
    char *response;
    cJSON *root, *result, *params;
    char *session_id = NULL, *nonce = NULL;
    bool ret = false;
    int retry = 0;

    if (!jsonrpc_connect(pool))
        goto out;

    while (retry < 2) {
        req = jsonrpc_req("mining.subscribe", "", NULL, NULL);
        if (!req)
            goto out;

        response = jsonrpc_call(req, pool->sock, &tok, JSONRPC_FLAG_NOCOMPACT);
        if (!response)
            goto out;

        root = json_tokener_parse_ex(tok, response, strlen(response));
        if (!root)
            goto out;

        result = json_object_get(root, "result");
        if (!result || !json_is_array(result)) {
            applog(LOG_WARNING, "Stratum subscribe response invalid: %s", response);
            goto out;
        }

        if (!json_array_get(result, 0, &params) || !json_is_array(params))
            goto out;

        session_id = strdup(json_string_value(json_array_get(params, 0)));
        if (!session_id)
            goto out;

        if (!json_array_get(params, 1, &params) || !json_is_string(params))
            goto out;

        nonce = strdup(json_string_value(params));
        if (!nonce)
            goto out;

        free(pool->session_id);
        pool->session_id = session_id;
        free(pool->nonce);
        pool->nonce = nonce;

        applog(LOG_DEBUG, "Stratum session initialized for pool %s with session ID: %s", pool->url, session_id);
        ret = true;
        break;

    out:
        if (tok)
            json_tokener_free(tok);
        if (response)
            free(response);
        if (root)
            json_object_put(root);
        if (req)
            jsonrpc_free(req);
        if (!ret && !retry)
            retry++;
        else
            break;
    }

    return ret;
}
